private fun decodePhoneEdgeCases(vararg chunks: String): List<PhoneEdgeCase> =
    chunks.flatMap { chunk ->
        chunk.split('\u001E').map { row ->
            val f = row.split('\u001F')
            PhoneEdgeCase(f[0], f[1], f[2].takeIf { f[3].isNotEmpty() }, f[3] == "1", f[4], f[5])
        }
    }
